/**
 * Normalize URLs for media generated by this application.
 * Older jobs may have persisted the public IP without its non-standard port;
 * the path is still valid, so it can be safely rebuilt from the current base.
 */
export function normalizeGeneratedMediaUrl(value, publicBaseUrl) {
  const raw = String(value || '').trim()
  const base = String(publicBaseUrl || '').trim().replace(/\/+$/, '')
  if (!raw || !base) return raw || null

  let parsed
  let configured
  try {
    parsed = new URL(raw)
    configured = new URL(base)
  } catch {
    return raw
  }

  if (!/^\/generated\/(?:video|audio|frame|export)\//i.test(parsed.pathname)) {
    return raw
  }

  return `${configured.origin}${parsed.pathname}${parsed.search}${parsed.hash}`
}

